from pathlib import Path
import json,html,hashlib,collections
out=Path('outputs/offline-web-articles-v2');m=json.loads((out/'manifest.json').read_text(encoding='utf-8'));rows=[r for r in m['documents'] if r['status']=='ready']
for r in rows:assert hashlib.sha256(Path(r['prepared_file']).read_bytes()).hexdigest()==r['prepared_sha256']
parts=['<!doctype html><meta charset="utf-8"><title>Offline website article catalogue</title><style>body{font:17px system-ui;max-width:1050px;margin:40px auto;padding:20px}input{padding:12px;width:95%}li{margin:14px 0}small{color:#555}</style><h1>Offline website article catalogue</h1><p>Historical mirror started June 2021. Incomplete capture. Website claims have not been independently verified. Original pages may attempt online requests; disconnect the internet for strictly offline browsing.</p><input id="q" placeholder="Filter titles" oninput="document.querySelectorAll(\'li\').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(this.value.toLowerCase()))"><ul>']
for r in sorted(rows,key=lambda x:x['title'].lower()):
 parts.append('<li><a href="'+html.escape(Path(r['source_path']).as_uri(),quote=True)+'">'+html.escape(r['title'])+'</a> <small>'+html.escape(r['domain'])+'</small> · <a href="'+html.escape(Path(r['prepared_file']).as_uri(),quote=True)+'">search text</a></li>')
parts.append('</ul>');(out/'browse-articles.html').write_text('\n'.join(parts),encoding='utf-8')
c=collections.Counter(r['domain'] for r in rows)
(out/'README.md').write_text(f'''# Offline website articles\n\nPrepared from an incomplete HTTrack mirror started 10 June 2021.\n\nArticle files: {dict(c)}. Exclusions and source paths are in manifest.json. All output file hashes checked.\n\nOpen browse-articles.html for a title filter with links to the original illustrated pages on D:. The originals must stay in their current location for those links. No original files were modified. External requests have not been stripped from the original HTML, and offline link/asset completeness is not verified.\n\nUpload upload/askaprepper to a NEW private collection named MAHASARAKHAM — Ask a Prepper (2021 archive). Upload upload/wikipedia-en separately if present, as MAHASARAKHAM — Wikipedia excerpts (2021 archive). These are historical secondary references, separate from WHO guidance. Not yet imported.\n\nScope: {m['scope']}. This is not an exhaustive extraction of all mirrored domains. No complete editorial review was performed; diagrams remain in original HTML, not in text.\n''',encoding='utf-8')
print(dict(c));print('Verified',len(rows),'hashes; catalogue created')
